import java.io.*;import java.net.*;import java.nio.file.*;
/** Regression: passive emote reads must never turn normal room transitions into errors. */
public class Battle751ServerCheck {
 static void ok(boolean b,String message){if(!b)throw new AssertionError(message);System.out.println("PASS: "+message);}
 static void empty(String token,String where)throws Exception{DataInputStream data=Equipment718ServerCheck.call(token,"battleemotes",null);for(int i=0;i<6;i++)ok(data.readUnsignedByte()==255&&data.readUnsignedShort()==0,"Empty emote slot in "+where);}
 public static void main(String[] args)throws Exception{CloudStore.Memory store=new CloudStore.Memory();store.register("a@751.test","test-password-123","A");store.register("b@751.test","test-password-123","B");try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){
 ServerCheck.base="http://127.0.0.1:"+server.port();String a=Equipment718ServerCheck.login("a@751.test"),b=Equipment718ServerCheck.login("b@751.test");empty(a,"lobby");int id=Equipment718ServerCheck.call(a,"create",out->{out.writeByte(1);out.writeByte(0);out.writeByte(-1);}).readInt();Equipment718ServerCheck.call(b,"join",out->{out.writeInt(id);out.writeByte(1);});GunnyServer.Room room=server.rooms.get(id);empty(a,"waiting room");synchronized(room){room.strict=false;room.start();room.phase=3;}empty(a,"loading");synchronized(room){room.phase=1;}Equipment718ServerCheck.call(a,"battleemote",out->out.writeByte(5));DataInputStream data=Equipment718ServerCheck.call(b,"battleemotes",null);ok(data.readUnsignedByte()==5&&data.readUnsignedShort()>0,"Emotes still reach the opponent during active battle");synchronized(room){room.phase=2;}empty(a,"results");Equipment718ServerCheck.reject(a,"battleemote",out->out.writeByte(1),"Sending emotes outside battle remains rejected");}System.out.println("All battle 7.5.1 server checks passed");}
}
